// ── EDIT ME ────────────────────────────────────────────
// limit  : how many open PRs to gate this run (each takes ~1.5-2 min, and the
//          bridge skips PRs whose head SHA was already gated, so this converges)
// dryRun : true  = run the gates, publish NOTHING to GitHub
//          false = publish commit statuses (the real local CI)  <-- live setting
// pr     : a specific PR number, or null to let the bridge pick
const limit = 3;
const dryRun = false;
const pr = null;

return [{ json: { limit: limit, dryRun: dryRun, pr: pr,
                  body: { limit: limit, dryRun: dryRun, pr: pr } } }];

const d = $input.first().json;
const stdout = String(d.stdout || '');
const stderr = String(d.stderr || '');
const tail = stdout.split('\n').filter(function (l) { return l.trim().length > 0; }).slice(-18).join('\n');
return [{ json: {
  ok: d.ok === true,
  exitCode: (d.exitCode !== undefined ? d.exitCode : null),
  durationSec: (d.durationSec !== undefined ? d.durationSec : null),
  tail: tail,
  stderrTail: stderr.split('\n').filter(function (l) { return l.trim().length > 0; }).slice(-6).join('\n')
} }];

parameters.jsonBody:
={{ JSON.stringify({channel: 'C0C0UPLGY12', text: `JARVIS local CI — PR gating run

exit: ${$json.exitCode}
duration: ${$json.durationSec}s
ok: ${$json.ok}

${$json.tail ? $json.tail.substring(0, 1200) : '(no stdout)'}${$json.stderrTail ? '
--- stderr ---
' + $json.stderrTail.substring(0, 400) : ''}` }) }}

parameters.jsCode:
// The bridge answers HTTP 200 even when the gate failed (ok:false), and the
// HTTP node keeps neverError on, so without this node a failed run would be
// recorded as a SUCCESS. That is the same false-green the bridge itself was
// fixed to stop, one layer up.
//
// Read the gate result by NAME: $input here is Slack's API response
// ({ok:true, ts:...}), not the CI summary.
const d = $('Summarize Result').first().json;
if (d.ok !== true) {
  throw new Error(
    'CI gate failed (exit ' + d.exitCode + ', ' + d.durationSec + 's): ' +
    String(d.stderrTail || d.tail || 'no detail').slice(0, 500)
  );
}
return [{ json: d }];
